def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    total_cells = 26 * 99
    has_cell = [False] * total_cells
    state = [0] * total_cells  # 0: unvisited, 1: visiting, 2: done
    values: list[int | str] = [0] * total_cells
    asts: list[tuple | None] = [None] * total_cells

    def cell_to_idx(name: str) -> int:
        return (int(name[1:]) - 1) * 26 + (ord(name[0]) - 65)

    def tokenize(s: str) -> list[tuple[str, object]]:
        tokens: list[tuple[str, object]] = []
        n = len(s)
        i = 0
        while i < n:
            ch = s[i]
            if ch.isspace():
                i += 1
            elif ch.isdigit():
                j = i + 1
                while j < n and s[j].isdigit():
                    j += 1
                tokens.append(("NUM", int(s[i:j])))
                i = j
            elif "A" <= ch <= "Z":
                j = i + 1
                while j < n and s[j].isalnum():
                    j += 1
                word = s[i:j]
                if word in ("SUM", "MIN", "MAX", "IF"):
                    tokens.append(("FUNC", word))
                else:
                    tokens.append(("CELL", cell_to_idx(word)))
                i = j
            elif ch == "<":
                if i + 1 < n and s[i + 1] in ("=", ">"):
                    tokens.append(("OP", s[i : i + 2]))
                    i += 2
                else:
                    tokens.append(("OP", "<"))
                    i += 1
            elif ch == ">":
                if i + 1 < n and s[i + 1] == "=":
                    tokens.append(("OP", ">="))
                    i += 2
                else:
                    tokens.append(("OP", ">"))
                    i += 1
            elif ch == "=":
                tokens.append(("OP", "="))
                i += 1
            else:
                tokens.append((ch, ch))
                i += 1
        tokens.append(("EOF", ""))
        return tokens

    def parse(tokens: list[tuple[str, object]]) -> tuple:
        pos = 0

        def parse_expr() -> tuple:
            nonlocal pos
            node = parse_term()
            while tokens[pos][0] in ("+", "-"):
                op = tokens[pos][0]
                pos += 1
                right = parse_term()
                node = ("BIN", op, node, right)
            return node

        def parse_term() -> tuple:
            nonlocal pos
            node = parse_unary()
            while tokens[pos][0] in ("*", "/"):
                op = tokens[pos][0]
                pos += 1
                right = parse_unary()
                node = ("BIN", op, node, right)
            return node

        def parse_unary() -> tuple:
            nonlocal pos
            neg_count = 0
            while tokens[pos][0] == "-":
                pos += 1
                neg_count += 1
            node = parse_atom()
            if neg_count & 1:
                node = ("NEG", node)
            return node

        def parse_atom() -> tuple:
            nonlocal pos
            tok_kind, tok_val = tokens[pos]
            if tok_kind == "NUM":
                pos += 1
                return ("NUM", tok_val)
            if tok_kind == "CELL":
                pos += 1
                return ("CELL", tok_val)
            if tok_kind == "(":
                pos += 1
                node = parse_expr()
                pos += 1  # ')'
                return node
            # FUNC
            pos += 2  # func name and '('
            if tok_val == "IF":
                left = parse_expr()
                op = tokens[pos][1]
                pos += 1
                right = parse_expr()
                pos += 1  # ','
                then_branch = parse_expr()
                pos += 1  # ','
                else_branch = parse_expr()
                pos += 1  # ')'
                return ("IF", op, left, right, then_branch, else_branch)
            args = []
            while True:
                if tokens[pos][0] == "CELL" and tokens[pos + 1][0] == ":":
                    c1 = tokens[pos][1]
                    c2 = tokens[pos + 2][1]
                    pos += 3
                    r1, col1 = divmod(c1, 26)
                    r2, col2 = divmod(c2, 26)
                    min_r, max_r = (r1, r2) if r1 <= r2 else (r2, r1)
                    min_c, max_c = (col1, col2) if col1 <= col2 else (col2, col1)
                    args.append(("RANGE", min_r, max_r, min_c, max_c))
                else:
                    args.append(("ARG", parse_expr()))
                if tokens[pos][0] == ",":
                    pos += 1
                else:
                    break
            pos += 1  # ')'
            return ("AGG", tok_val, args)

        return parse_expr()

    cell_indices: dict[str, int] = {}
    for name, content in cells.items():
        idx = cell_to_idx(name)
        cell_indices[name] = idx
        has_cell[idx] = True
        raw = content.strip()
        if raw.startswith("="):
            asts[idx] = parse(tokenize(raw[1:]))
        else:
            values[idx] = int(raw)
            state[idx] = 2

    def eval_cell(root_idx: int) -> int | str:
        if state[root_idx] == 2:
            return values[root_idx]
        state[root_idx] = 1
        stack: list = [("CELL_DONE", root_idx)]
        node: tuple | None = asts[root_idx]
        val: int | str = 0

        while True:
            if node is not None:
                kind = node[0]
                if kind == "NUM":
                    val = node[1]
                    node = None
                elif kind == "CELL":
                    idx = node[1]
                    if not has_cell[idx]:
                        val = 0
                        node = None
                    else:
                        st = state[idx]
                        if st == 2:
                            val = values[idx]
                            node = None
                        elif st == 1:
                            val = "#CYCLE!"
                            node = None
                        else:
                            state[idx] = 1
                            stack.append(("CELL_DONE", idx))
                            node = asts[idx]
                elif kind == "NEG":
                    stack.append(("NEG_DONE",))
                    node = node[1]
                elif kind == "BIN":
                    stack.append(("BIN_L", node[1], node[3]))
                    node = node[2]
                elif kind == "IF":
                    stack.append(("IF_L", node[1], node[3], node[4], node[5]))
                    node = node[2]
                else:  # AGG
                    stack.append(["AGG_STEP", node[1], node[2], 0, -1, -1, False, 0, False])
                    node = None
            else:
                if not stack:
                    return val
                frame = stack[-1]
                fkind = frame[0]
                if fkind == "CELL_DONE":
                    stack.pop()
                    idx = frame[1]
                    values[idx] = val
                    state[idx] = 2
                elif fkind == "NEG_DONE":
                    stack.pop()
                    if type(val) is int:
                        val = -val
                elif fkind == "BIN_L":
                    stack.pop()
                    if type(val) is int:
                        stack.append(("BIN_R", frame[1], val))
                        node = frame[2]
                elif fkind == "BIN_R":
                    stack.pop()
                    if type(val) is int:
                        op = frame[1]
                        lv = frame[2]
                        if op == "+":
                            val = lv + val
                        elif op == "-":
                            val = lv - val
                        elif op == "*":
                            val = lv * val
                        else:  # '/'
                            if val == 0:
                                val = "#DIV/0!"
                            else:
                                q = abs(lv) // abs(val)
                                val = -q if (lv < 0) ^ (val < 0) else q
                elif fkind == "IF_L":
                    stack.pop()
                    if type(val) is int:
                        stack.append(("IF_R", frame[1], val, frame[3], frame[4]))
                        node = frame[2]
                elif fkind == "IF_R":
                    stack.pop()
                    if type(val) is int:
                        op = frame[1]
                        lv = frame[2]
                        if op == "=":
                            cond = lv == val
                        elif op == "<>":
                            cond = lv != val
                        elif op == "<":
                            cond = lv < val
                        elif op == "<=":
                            cond = lv <= val
                        elif op == ">":
                            cond = lv > val
                        else:  # '>='
                            cond = lv >= val
                        node = frame[3] if cond else frame[4]
                else:  # AGG_STEP
                    func = frame[1]
                    args = frame[2]
                    arg_i = frame[3]
                    r = frame[4]
                    c = frame[5]
                    agg_has_val = frame[6]
                    acc = frame[7]
                    if frame[8]:
                        if type(val) is not int:
                            stack.pop()
                            continue
                        if func == "SUM":
                            acc += val
                        elif func == "MIN":
                            if not agg_has_val or val < acc:
                                acc = val
                                agg_has_val = True
                        else:  # MAX
                            if not agg_has_val or val > acc:
                                acc = val
                                agg_has_val = True

                    while True:
                        if arg_i >= len(args):
                            stack.pop()
                            val = acc if (func == "SUM" or agg_has_val) else 0
                            break
                        arg = args[arg_i]
                        if arg[0] == "ARG":
                            frame[3] = arg_i + 1
                            frame[4] = -1
                            frame[6] = agg_has_val
                            frame[7] = acc
                            frame[8] = True
                            node = arg[1]
                            break
                        else:  # RANGE
                            _, min_r, max_r, min_c, max_c = arg
                            if r == -1:
                                r = min_r
                                c = min_c
                            need_eval = -1
                            error_val = None
                            while r <= max_r:
                                base = r * 26
                                while c <= max_c:
                                    idx = base + c
                                    c += 1
                                    if not has_cell[idx]:
                                        continue
                                    st = state[idx]
                                    if st == 2:
                                        v = values[idx]
                                        if type(v) is not int:
                                            error_val = v
                                            break
                                        if func == "SUM":
                                            acc += v
                                        elif func == "MIN":
                                            if not agg_has_val or v < acc:
                                                acc = v
                                                agg_has_val = True
                                        else:
                                            if not agg_has_val or v > acc:
                                                acc = v
                                                agg_has_val = True
                                    elif st == 1:
                                        error_val = "#CYCLE!"
                                        break
                                    else:
                                        need_eval = idx
                                        break
                                if error_val is not None or need_eval != -1:
                                    break
                                r += 1
                                c = min_c

                            if error_val is not None:
                                stack.pop()
                                val = error_val
                                break
                            if need_eval != -1:
                                frame[3] = arg_i
                                frame[4] = r
                                frame[5] = c
                                frame[6] = agg_has_val
                                frame[7] = acc
                                frame[8] = True
                                state[need_eval] = 1
                                stack.append(("CELL_DONE", need_eval))
                                node = asts[need_eval]
                                break
                            arg_i += 1
                            r = -1

    return {name: eval_cell(idx) for name, idx in cell_indices.items()}
